10	/// Registers the `export` feature into the project's single `get_it`
11	/// instance (`sl`) — mirrors `capture_injection.dart`'s own shape.
12	/// [ExportJobCubit] is a `registerFactory`, not a `lazySingleton` (Code
13	/// Map: "`registerFactory<TextEntryCubit>` one-shot-cubit precedent") — a
14	/// fresh instance per download-icon tap, closed by the call site itself
15	/// once its sheet is gone (`ExportStatusSheet.show()`), never by a
16	/// `get_it` `dispose:` hook. No Hive box here (AD-15: export jobs are
17	/// never persisted locally).
18	void registerExportFeature() {
19	  sl.registerLazySingleton<ExportRemoteDataSource>(
20	    () => ExportRemoteDataSource(sl<ApiClient>()),
21	  );
22	
23	  sl.registerLazySingleton<ExportRepository>(
24	    () => ExportRepositoryImpl(remoteDataSource: sl<ExportRemoteDataSource>()),
25	  );
26	
27	  // spec-7-2 — the real download-opener; a stateless wrapper over
28	  // `url_launcher`, so a singleton is as cheap as a factory here.
29	  sl.registerLazySingleton<DownloadOpener>(() => UrlLauncherDownloadOpener());
30	
31	  sl.registerFactory<ExportJobCubit>(
32	    () => ExportJobCubit(sl<ExportRepository>(), sl<DownloadOpener>()),
33	  );
34	}
